suggested diff:
```diff
diff --git a/src/script/descriptor.cpp b/src/script/descriptor.cpp
index 3ae2da81d..29dbfa3a7 100644
--- a/src/script/descriptor.cpp
+++ b/src/script/descriptor.cpp
@@ -2828,15 +2828,29 @@ std::vector<std::unique_ptr<DescriptorImpl>> ParseScript(uint32_t& key_exp_index
         error = "A function is needed within P2WSH";
         return {};
     }
-    // Quote the function name only if it is 16 characters or fewer: every key is longer, and a bare key has no '('
+    // Show the expression as "name(...)rest", where the arguments are never quoted, the name
+    // only if it is 16 characters or fewer (every key is longer, and a bare key has no '('),
+    // and the text after the matching ')' only if it is no longer than MAX_QUOTED_TOKEN_CHARS.
     constexpr size_t MAX_FUNCTION_NAME_CHARS{16};
     const std::string_view expr_text{expr.begin(), expr.end()};
-    const size_t paren{expr_text.find('(')};
-    if (paren == std::string_view::npos || paren == 0 || paren > MAX_FUNCTION_NAME_CHARS) {
+    const size_t open{expr_text.find('(')};
+    if (open == std::string_view::npos || open == 0 || open > MAX_FUNCTION_NAME_CHARS) {
         error = "Not a valid descriptor function";
-    } else {
-        error = strprintf("'%s(...' is not a valid descriptor function", expr_text.substr(0, paren));
+        return {};
+    }
+    std::string shown{strprintf("%s(...", expr_text.substr(0, open))};
+    int depth{0};
+    for (size_t i{open}; i < expr_text.size(); ++i) {
+        if (expr_text[i] == '(') {
+            ++depth;
+        } else if (expr_text[i] == ')' && --depth == 0) {
+            const std::string_view rest{expr_text.substr(i + 1)};
+            shown += ')';
+            shown += rest.size() <= MAX_QUOTED_TOKEN_CHARS ? rest : std::string_view{"..."};
+            break;
+        }
     }
+    error = strprintf("Invalid descriptor expression '%s'", shown);
     return {};
 }
